@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">University Course Catalog</h1>
        <p class="lead text-muted">Explore departments, browse courses, and submit your enrollment request.</p>
    </div>

    <section class="mb-5">
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-6 col-lg-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code</h5>
                            <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                            <p class="card-text small">@course.Credits credits &bull; @course.DepartmentName</p>
                            <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section>
        <h2 class="mb-3">Departments</h2>
        <div class="row">
            @foreach (var dept in _departments)
            {
                <div class="col-md-6 col-lg-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text small">@dept.Description</p>
                            <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">Browse Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@rendermode InteractiveServer
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Browse Courses</h1>

    <div class="row mb-4">
        <div class="col-md-6 mb-2">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="_searchTerm" @bind:event="oninput" @onkeyup="ApplyFilters" />
        </div>
        <div class="col-md-4 mb-2">
            <select class="form-select" @bind="_selectedDepartmentId" @bind:after="ApplyFilters">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @if (_courses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in _courses)
                    {
                        <tr>
                            <td>@course.Code</td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> _courses = new();
    private List<Department> _departments = new();
    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        _selectedDepartmentId = DepartmentId ?? 0;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = _selectedDepartmentId > 0 ? _selectedDepartmentId : null;
        _courses = CatalogService.GetCourses(_searchTerm, deptFilter);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

<div class="container py-4">
    @if (_course is null)
    {
        <div class="alert alert-warning">Course not found.</div>
        <a href="/courses" class="btn btn-secondary">Back to Courses</a>
    }
    else
    {
        <nav aria-label="breadcrumb" class="mb-3">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/courses?departmentId=@_course.DepartmentId">@_course.DepartmentName</a></li>
                <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
            </ol>
        </nav>

        <h1>@_course.Title</h1>
        <span class="badge bg-secondary mb-3">@_course.Code</span>

        <div class="row mt-4">
            <div class="col-md-8">
                <h4>Description</h4>
                <p>@_course.Description</p>

                <h4 class="mt-4">Schedule</h4>
                <p><i class="bi bi-clock"></i> @_course.Schedule</p>

                <h4 class="mt-4">Credits</h4>
                <p>@_course.Credits credit hours</p>
            </div>
            <div class="col-md-4">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@_course.InstructorName</h6>
                        <p class="card-text small">@_course.InstructorBio</p>
                    </div>
                </div>
                <a href="/enroll?courseId=@_course.Id" class="btn btn-success w-100 mt-3">Request Enrollment</a>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified once it is processed.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <div class="row">
            <div class="col-md-8 col-lg-6">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                        <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g. 12345678" />
                        <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(_model);
        if (success)
        {
            var course = CatalogService.GetCourse(_model.CourseId);
            _selectedCourseTitle = course?.Title ?? "Unknown Course";
            _submitted = true;
        }
    }
}

